            .thenDo(async () => {
              await token.document.update(newUpdates);
            })

            .effect()
            .file("jb2a.sleep.cloud.01.dark_purple")
            .atLocation(token)
            .delay(200)
            .opacity(0.5)
            .scaleOut(0.5, 1000, { ease: "easeOutCubic" })
            .scaleToObject(2)
            .belowTokens()
            .duration(1000)
            .fadeOut(1000)

            .effect()
            .file("jb2a.particles.outward.purple.02.03")
            .name("DisguiseSelf")
            .atLocation(token)
            .delay(200)
            .scaleToObject(1.5)
            .zIndex(2)
            .scaleIn(0, 200, { ease: "easeOutCubic" })
            .attachTo(token, { bindAlpha: false })
            .persist()
            .fadeIn(760)
            .fadeOut(2500)
            .play();
        },
      },
    },
    default: "change:",
  }).render(true);
}
if (args[0] === "off") {
  let originalUpdates = token.document.getFlag("world", "disguiseSelf");

  // Deconstruct originalUpdates to create revertUpdates
  const {
    originalImage,
    originalHeight,
    originalWidth,
    originalRing,
  } = originalUpdates;

  const revertUpdates = {
    "texture.src": originalImage,
    height: originalHeight,
    width: originalWidth,
    ring: originalRing,
  };
  console.log("revertUpdates", revertUpdates);
  await token.document.unsetFlag("world", "disguiseSelf", null);
  new Sequence().animation().on(token).opacity(1).play();

  await Sequencer.EffectManager.endEffects({
    name: "DisguiseSelf",
    object: token,
  });
  await token.document.update(revertUpdates);
  ChatMessage.create({
    content: `${itemName} wears off.`,
    speaker: ChatMessage.getSpeaker({ actor: token.actor }),
  });
}
